//! Echoes the virtual COM port (SERCOM1, PB00/PB01, 115,200 baud) through
//! a `BufferedUart`: SERCOM v1's single interrupt vector driving the rings.
//! LED0 toggles with each chunk echoed.

#![no_std]
#![no_main]
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use embassy_executor::Spawner;
use panic_halt as _;
use pic32c_hal::gpio::{Level, Output};
use pic32c_hal::uart::{self, BufferedUart};
use pic32c_hal::{bind_interrupts, peripherals};
use static_cell::ConstStaticCell;

bind_interrupts!(struct Irqs {
    SERCOM1 => uart::InterruptHandler<peripherals::SERCOM1>;
});

static TX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);
static RX: ConstStaticCell<[u8; 256]> = ConstStaticCell::new([0; 256]);

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let p = pic32cm_pl10_curiosity_nano::init();
    let mut led = Output::new(p.PB02, Level::High);
    let mut config = uart::Config::default();
    config.baudrate = 115_200;
    let uart = BufferedUart::new(p.SERCOM1, p.PB00, p.PB01, Irqs, TX.take(), RX.take(), config).unwrap();
    let (mut tx, mut rx) = uart.split();
    let _ = tx.write_all(b"\r\npic32cm-pl10-curiosity-nano uart_echo\r\n").await;
    let mut buffer = [0u8; 64];
    loop {
        if let Ok(n) = rx.read(&mut buffer).await {
            let _ = tx.write_all(&buffer[..n]).await;
            led.toggle();
        }
    }
}
